import http from 'node:http'
const started = Date.now()
const chunks = []
await new Promise((resolve, reject) => {
  http.get('http://localhost:3456/', (response) => {
    console.log('status', response.statusCode)
    response.setEncoding('utf8')
    response.on('data', (chunk) => chunks.push({ at: Date.now() - started, text: chunk }))
    response.on('end', resolve)
  }).on('error', reject)
})
const shell = chunks.find((chunk) => chunk.text.includes('Loading...'))
const data = chunks.find((chunk) => chunk.text.includes('Acme'))
console.log('shell:', shell && { afterMs: shell.at, heading: shell.text.includes('Dashboard'), sections: ['Total Revenue', 'Total Invoices', 'Revenue', 'Latest Invoices'].every((label) => shell.text.includes(label)) })
console.log('streamed data:', data && { afterMs: data.at, revenue: data.text.includes('1,234'), invoice: data.text.includes('Acme') })
if ("'!shell || !data || shell.at >= data.at) process.exitCode = 1
EOF'

